(753666, 81957, 18820, '<td valign="top">GREAT PICTURE -- I tried for the same concept - (mine came out a little sloppy) -- no one understood the deep depth of field in the illusion! I''m giving you a 10!</td>', 'GREAT PICTURE -- I tried for the same concept - (mine came out a little sloppy) -- no one understood the deep depth of field in the illusion! I''m giving you a 10!', '2004-06-07 17:05:16.000000', NULL, 1),
