(753762, 81482, 8860, '<td valign="top">Hey - I live in Enfield and there ain''t no point like this one anywhere near!! Nice view and meets the challenge.</td>', 'Hey - I live in Enfield and there ain''t no point like this one anywhere near!! Nice view and meets the challenge.', '2004-06-07 17:48:08.000000', NULL, 1),
(753782, 80816, 8860, '<td valign="top">Looks like you focused to close here. Around 2/3 of the depth into your image would give you hyperfocus and thus meet the challenge. Aside form that it''s a pleasant pic but not much of interest outside of the challenge boundary.</td>', 'Looks like you focused to close here. Around 2/3 of the depth into your image would give you hyperfocus and thus meet the challenge. Aside form that it''s a pleasant pic but not much of interest outside of the challenge boundary.', '2004-06-07 17:53:14.000000', NULL, 1),
(753794, 81455, 8860, '<td valign="top">Yup - that''s deep alright. If not in the top 3 then this will be on the front page, deservedly. Great scene and lovely contrast - although the left side appears a little too burned and is heavy as a result.</td>', 'Yup - that''s deep alright. If not in the top 3 then this will be on the front page, deservedly. Great scene and lovely contrast - although the left side appears a little too burned and is heavy as a result.', '2004-06-07 17:55:28.000000', NULL, 1),
