(753868, 81550, 16965, '<td valign="top">Great image, well exposed, and very interesting composition, but there isn''t much deep DOF indications here.</td>', 'Great image, well exposed, and very interesting composition, but there isn''t much deep DOF indications here.', '2004-06-07 18:47:59.000000', NULL, 1),
(753871, 81477, 19672, '<td valign="top">Shouldn''t this be in the "waiting" challenge....LOL</td>', 'Shouldn''t this be in the "waiting" challenge....LOL', '2004-06-07 18:49:00.000000', NULL, 1),
(753873, 80457, 16965, '<td valign="top">Great image of the moon. but unless I count the crator shadows, there isn''t much indication of a deep DOF here.  The image is flat, and without something MUCH closer in the foreground, it stays that way.</td>', 'Great image of the moon. but unless I count the crator shadows, there isn''t much indication of a deep DOF here.  The image is flat, and without something MUCH closer in the foreground, it stays that way.', '2004-06-07 18:49:23.000000', NULL, 1),
(753877, 80655, 16965, '<td valign="top">Great, Really Deep DOF.  By far the best Guitar pic that has been posted.</td>', 'Great, Really Deep DOF.  By far the best Guitar pic that has been posted.', '2004-06-07 18:50:43.000000', NULL, 1),
(753880, 81677, 16965, '<td valign="top">An indication of Depth, maybe, but not very strong Depth of Field here.  The bulb of the key is out of focus in the foreground, whilst the slot and key touching it are perfectly in focus.</td>', 'An indication of Depth, maybe, but not very strong Depth of Field here.  The bulb of the key is out of focus in the foreground, whilst the slot and key touching it are perfectly in focus.', '2004-06-07 18:52:02.000000', NULL, 1),
(753883, 81507, 16965, '<td valign="top">Macro shots are very difficult to obtain Deep depth of field.  This would have benefitted from a smaller (higher numbered) Apature.  Even some of the ''bulbs'' in the floweres indicate how shallow the depth of field really is.</td>', 'Macro shots are very difficult to obtain Deep depth of field.  This would have benefitted from a smaller (higher numbered) Apature.  Even some of the ''bulbs'' in the floweres indicate how shallow the depth of field really is.', '2004-06-07 18:53:34.000000', NULL, 1),
(753889, 81627, 16965, '<td valign="top">what a beautiful shot.  It looks a bit oversharpened, though.</td>', 'what a beautiful shot.  It looks a bit oversharpened, though.', '2004-06-07 18:55:47.000000', NULL, 1),
(753896, 81708, 20941, '<td valign="top">artistic composition nice dof</td>', 'artistic composition nice dof', '2004-06-07 18:58:54.000000', NULL, 1),
