INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(753912, 80837, 20941, '<td valign="top">great example of DOF! nice</td>', 'great example of DOF! nice', '2004-06-07 19:05:53.000000', NULL, 1),
(753916, 81837, 19672, '<td valign="top">OKay...i feel like those old "Highlights" kid''s magazines....so WHAT IS IT?</td>', 'OKay...i feel like those old "Highlights" kid''s magazines....so WHAT IS IT?', '2004-06-07 19:07:33.000000', NULL, 1),
(753919, 81832, 19672, '<td valign="top">Ah....another later entry for the "Threes" competition...eh?</td>', 'Ah....another later entry for the "Threes" competition...eh?', '2004-06-07 19:08:47.000000', NULL, 1),
(753929, 81915, 7322, '<td valign="top">What can I say? This is not the best execution of a forced perspective shot, for one thing. Generally, you choose a very simple background so that you don''t need to do all that Photoshop manipulation. What I''m seeing is a very heavy, rather clumsy use of the smudge tool on the background. I can''t figure out why the bottom kid''s head is flattened. I know it is supposed to look like the other kid is sitting on his head but it just looks wierd.The way the bottom kid''s shirt  and pants fit it looks like his head is twisted on backwards. Very disorienting. I''m guessing that you intended this to show Deep DOF by its necessity for this trick.</td>', 'What can I say? This is not the best execution of a forced perspective shot, for one thing. Generally, you choose a very simple background so that you don''t need to do all that Photoshop manipulation. What I''m seeing is a very heavy, rather clumsy use of the smudge tool on the background. I can''t figure out why the bottom kid''s head is flattened. I know it is supposed to look like the other kid is sitting on his head but it just looks wierd.The way the bottom kid''s shirt  and pants fit it looks like his head is twisted on backwards. Very disorienting. I''m guessing that you intended this to show Deep DOF by its necessity for this trick.', '2004-06-07 19:20:09.000000', NULL, 1),
(753932, 81909, 7322, '<td valign="top">I can''t tell if you are holding this coin up to an actual landscape or if the landscape is a photo in the background. Either way, the fingers, particularly the glaring white thumbnail makes this a very unpleasant shot for me. Sorry.</td>', 'I can''t tell if you are holding this coin up to an actual landscape or if the landscape is a photo in the background. Either way, the fingers, particularly the glaring white thumbnail makes this a very unpleasant shot for me. Sorry.', '2004-06-07 19:22:16.000000', NULL, 1),
(753933, 81820, 16636, '<td valign="top">really nice image like the symetry, sorry but the border dosen''t do anything for me - 7</td>', 'really nice image like the symetry, sorry but the border dosen''t do anything for me - 7', '2004-06-07 19:23:12.000000', NULL, 1),
(753937, 81832, 7322, '<td valign="top">This does not show Deep depth of field. It shows shallow depth of field. Deep depth of field is when the background is in focus to infinity. It''s an interesting subject but I don''t think this is the best approach to photographing such texturally interesting objects. Try lighting it from the side to capture all the nooks more dramatically. Also, try moving in closer so that the mushrooms become more significant to the frame.</td>', 'This does not show Deep depth of field. It shows shallow depth of field. Deep depth of field is when the background is in focus to infinity. It''s an interesting subject but I don''t think this is the best approach to photographing such texturally interesting objects. Try lighting it from the side to capture all the nooks more dramatically. Also, try moving in closer so that the mushrooms become more significant to the frame.', '2004-06-07 19:25:53.000000', NULL, 1),
(753940, 81112, 7322, '<td valign="top">This is using shallow depth of field. The background is blurred. Deep DOF is when everything in the seen is in focus to infinity. <br/>The subject is fairly interesting. The lighting is a bit flat on the hands and the focus doesn''t appear to good at the lower edge of the subject. This chunky border is very unattracttive. Next time, try using the maximum size of 640. This image is rather small to make much of an impact.</td>', 'This is using shallow depth of field. The background is blurred. Deep DOF is when everything in the seen is in focus to infinity. The subject is fairly interesting. The lighting is a bit flat on the hands and the focus doesn''t appear to good at the lower edge of the subject. This chunky border is very unattracttive. Next time, try using the maximum size of 640. This image is rather small to make much of an impact.', '2004-06-07 19:28:42.000000', NULL, 1),
(753942, 81818, 7322, '<td valign="top">This appears very orange on my monitor. The cropping is extremely tight for the subject. Next time consider a horizontal format if possible. This image is rather small to get much of an impression of the image quality.</td>', 'This appears very orange on my monitor. The cropping is extremely tight for the subject. Next time consider a horizontal format if possible. This image is rather small to get much of an impression of the image quality.', '2004-06-07 19:30:38.000000', NULL, 1),
(753943, 81507, 7322, '<td valign="top">This is using shallow depth of field--the background is blurred. Deep DOF is when everything is in focus to infinity. As a macro it is decent. The background could be blurred quite a bit more. Perhaps a vertical composition or a square crop would have suited the subject better?</td>', 'This is using shallow depth of field--the background is blurred. Deep DOF is when everything is in focus to infinity. As a macro it is decent. The background could be blurred quite a bit more. Perhaps a vertical composition or a square crop would have suited the subject better?', '2004-06-07 19:32:23.000000', NULL, 1),
(753947, 81677, 7322, '<td valign="top">I find this a rather dull subject and an odd choice for this challenge. It isn''t displaying deep depth of field. A good part of the key is out of focus. Deep DOF should show everything to infinity in focus.</td>', 'I find this a rather dull subject and an odd choice for this challenge. It isn''t displaying deep depth of field. A good part of the key is out of focus. Deep DOF should show everything to infinity in focus.', '2004-06-07 19:34:38.000000', NULL, 1),
(753950, 81927, 7322, '<td valign="top">This is illustrating deep depth of field. It''s kind of a mundane view, sadly. The tree really detracts from the simplicity a shot like this should have.</td>', 'This is illustrating deep depth of field. It''s kind of a mundane view, sadly. The tree really detracts from the simplicity a shot like this should have.', '2004-06-07 19:35:54.000000', NULL, 1),
(753953, 81938, 7322, '<td valign="top">I don''t understand how this is meant to show deep depth of field. The foreground is quite blurred. With deep DOF everything from the foreground to infinity needs to be in focus. It''s an interesting view of the sunflowers although a bit off-balance. The top edge of the frame is nearly twice as wide as the lower edge and the same can be said for the left edge in relation to the right edge.</td>', 'I don''t understand how this is meant to show deep depth of field. The foreground is quite blurred. With deep DOF everything from the foreground to infinity needs to be in focus. It''s an interesting view of the sunflowers although a bit off-balance. The top edge of the frame is nearly twice as wide as the lower edge and the same can be said for the left edge in relation to the right edge.', '2004-06-07 19:38:28.000000', NULL, 1),
(753959, 81736, 7322, '<td valign="top">The focus on the workers looks rather weird to me, as if it has been overly manipulated in post-processing. It''s an interesting shot but I can''t really relate it to deep depth of field. The foreground appears to be out of focus, although it is so dark it is hard to tell. I can''t tell anything about the background as it is completely dark. The light doesn''t appear to be in sharp focus but that could be the flare. Deep depth of field requires that everything from the foreground to infinity be in focus.</td>', 'The focus on the workers looks rather weird to me, as if it has been overly manipulated in post-processing. It''s an interesting shot but I can''t really relate it to deep depth of field. The foreground appears to be out of focus, although it is so dark it is hard to tell. I can''t tell anything about the background as it is completely dark. The light doesn''t appear to be in sharp focus but that could be the flare. Deep depth of field requires that everything from the foreground to infinity be in focus.', '2004-06-07 19:41:37.000000', NULL, 1),
(753964, 81553, 7322, '<td valign="top">I guess this shot used deep DOF. It is hard to tell because there really isn''t much in the way of background or foreground. The subject itself is not presented in a way I find compelling. It does demonstrate in a way how deep DOF is achieved so I''m not sure why you didn''t just go out and take a shot of something using deep DOF to show off the advantages of the technique.</td>', 'I guess this shot used deep DOF. It is hard to tell because there really isn''t much in the way of background or foreground. The subject itself is not presented in a way I find compelling. It does demonstrate in a way how deep DOF is achieved so I''m not sure why you didn''t just go out and take a shot of something using deep DOF to show off the advantages of the technique.', '2004-06-07 19:45:32.000000', NULL, 1),
(753965, 81957, 7322, '<td valign="top">This is a well executed forced perspective shot and it does require deep depth of field to achieve. I don''t find the subject appealing, however. I''m sure others will. Good luck with it!</td>', 'This is a well executed forced perspective shot and it does require deep depth of field to achieve. I don''t find the subject appealing, however. I''m sure others will. Good luck with it!', '2004-06-07 19:47:59.000000', NULL, 1),
(753967, 81826, 7322, '<td valign="top">This just missed being a really nice photo, in my opinion. Unfortunately, the middle flamingo is growing out of the foreground flamingo''s head. The foreground flamingo isn''t anchored in the frame too well and yonder flamingo is overly cropped. This was a case where just moving your position a couple of inches might have elminated all these problems.  The middle and yonder flamingo are a bit overexposed. Nearly all the detail is lost on their backs.</td>', 'This just missed being a really nice photo, in my opinion. Unfortunately, the middle flamingo is growing out of the foreground flamingo''s head. The foreground flamingo isn''t anchored in the frame too well and yonder flamingo is overly cropped. This was a case where just moving your position a couple of inches might have elminated all these problems.  The middle and yonder flamingo are a bit overexposed. Nearly all the detail is lost on their backs.', '2004-06-07 19:51:39.000000', NULL, 1),
(753968, 81820, 7322, '<td valign="top">The crops appear extremely contrasty. There seems to be very little in the way of middle values. For this shot to work for me I would have had to seen the diagonals of the crop rows repeated throughout the frame.</td>', 'The crops appear extremely contrasty. There seems to be very little in the way of middle values. For this shot to work for me I would have had to seen the diagonals of the crop rows repeated throughout the frame.', '2004-06-07 19:54:07.000000', NULL, 1),
(753973, 81824, 7322, '<td valign="top">I find this a very mundane view of this subject. There are some strong horizontal lines in the shadows but I can''t see any visual harmony. They don''t lead the eye to any particular place in the frame. The chain link fence and sign are just clutter in this kind of shot. One think I like is the strong curve of the foremost road against the blue sky. This can be a visually exciting subject. Try shooting it from different viewpoints.</td>', 'I find this a very mundane view of this subject. There are some strong horizontal lines in the shadows but I can''t see any visual harmony. They don''t lead the eye to any particular place in the frame. The chain link fence and sign are just clutter in this kind of shot. One think I like is the strong curve of the foremost road against the blue sky. This can be a visually exciting subject. Try shooting it from different viewpoints.', '2004-06-07 19:58:11.000000', NULL, 1),
(753976, 81655, 7322, '<td valign="top">This place looks like a nice photo subject. The composition doesn''t work for me; the line of the rocks just leads the eye around the rather dull trees and right out of the frame. The lighting is very ho-hum. Try returning to this scene at a time of day when the light is more dramatic. Also, pay attention to the objects in a composition that create imaginary lines and ask yourself if you have framed the scene in a way that uses these lines to the best advantage.</td>', 'This place looks like a nice photo subject. The composition doesn''t work for me; the line of the rocks just leads the eye around the rather dull trees and right out of the frame. The lighting is very ho-hum. Try returning to this scene at a time of day when the light is more dramatic. Also, pay attention to the objects in a composition that create imaginary lines and ask yourself if you have framed the scene in a way that uses these lines to the best advantage.', '2004-06-07 20:03:16.000000', NULL, 1),
(753978, 81717, 7322, '<td valign="top">This is an interesting approach to framing a landscape. The foreground is very dark, however, and it doesn''t appear to be in as sharp focus as the background which needs to be the case in order to illustrate deep depth of field. The foreground fills a bit too much of the frame. The subject in the background is so far off all I can tell about it is it''s a white building of some sort. A frame like this can be helpful in leading the eye to a far off subject but in this case it is just overwhelming the subject.</td>', 'This is an interesting approach to framing a landscape. The foreground is very dark, however, and it doesn''t appear to be in as sharp focus as the background which needs to be the case in order to illustrate deep depth of field. The foreground fills a bit too much of the frame. The subject in the background is so far off all I can tell about it is it''s a white building of some sort. A frame like this can be helpful in leading the eye to a far off subject but in this case it is just overwhelming the subject.', '2004-06-07 20:06:02.000000', NULL, 1),
(753980, 81840, 7322, '<td valign="top">Perhaps it''s my monitors (I''ve viewed it on both my computers) but this was just too dark and too blue for me.</td>', 'Perhaps it''s my monitors (I''ve viewed it on both my computers) but this was just too dark and too blue for me.', '2004-06-07 20:07:49.000000', NULL, 1),
(753981, 80603, 7322, '<td valign="top">While motion blur can add visual interest to a photo I''m not finding that it''s working very hard in this shot. Perhaps if all the cars didn''t seem to be the same color? The whole scene appears rather mundane and grey.</td>', 'While motion blur can add visual interest to a photo I''m not finding that it''s working very hard in this shot. Perhaps if all the cars didn''t seem to be the same color? The whole scene appears rather mundane and grey.', '2004-06-07 20:09:51.000000', NULL, 1),
(753989, 81704, 15207, '<td valign="top">Excellent submission for this challenge. I love the geometric lines, the colours, everything. 10! I predict a ribbon!</td>', 'Excellent submission for this challenge. I love the geometric lines, the colours, everything. 10! I predict a ribbon!', '2004-06-07 20:24:09.000000', NULL, 1),
(753990, 81806, 15207, '<td valign="top">This is stunning. I can''t stop looking at it. I can see this working really well as a print. It''s definitely my favorite in this challenge - 10</td>', 'This is stunning. I can''t stop looking at it. I can see this working really well as a print. It''s definitely my favorite in this challenge - 10', '2004-06-07 20:24:38.000000', NULL, 1),
(753992, 81132, 15207, '<td valign="top">A perfect submission for this challenge. I find it is slightly too sharp, at least on my monitor (there are some noise and compression artifacts in the water as a result). however, I really love this. The composition is excellent. 10</td>', 'A perfect submission for this challenge. I find it is slightly too sharp, at least on my monitor (there are some noise and compression artifacts in the water as a result). however, I really love this. The composition is excellent. 10', '2004-06-07 20:25:20.000000', NULL, 1),
(753993, 81902, 15207, '<td valign="top">I really love this. I love the colours adn tones, the composition, everything. It''s perfect 10</td>', 'I really love this. I love the colours adn tones, the composition, everything. It''s perfect 10', '2004-06-07 20:25:48.000000', NULL, 1),
(753994, 81455, 15207, '<td valign="top">Really good submission for this challenge. It''s near perfect. I really love the sky and the black and white - it has a very ansel adams feel. 10</td>', 'Really good submission for this challenge. It''s near perfect. I really love the sky and the black and white - it has a very ansel adams feel. 10', '2004-06-07 20:26:25.000000', NULL, 1),
(753996, 81708, 15207, '<td valign="top">Really excellent submission for this challenge in many respects. I love all the angles. You have a great eye. Good luck - 9</td>', 'Really excellent submission for this challenge in many respects. I love all the angles. You have a great eye. Good luck - 9', '2004-06-07 20:26:51.000000', NULL, 1),
(754008, 81795, 14053, '<td valign="top">I like this shot. It meets the challenge well.  The bush in the lower left is a wee bit distracting Otherwise very good The building in the background resembles the railroad station I was at in Cumberland Maryland.</td>', 'I like this shot. It meets the challenge well.  The bush in the lower left is a wee bit distracting Otherwise very good The building in the background resembles the railroad station I was at in Cumberland Maryland.', '2004-06-07 20:41:21.000000', NULL, 1),
