(754292, 81150, 22734, '<td valign="top">nice effect but does horizon placement warrent the nice effect of its natural home?</td>', 'nice effect but does horizon placement warrent the nice effect of its natural home?', '2004-06-07 23:47:28.000000', NULL, 1),
