(754303, 81752, 3306, '<td valign="top">Good DOF. Satisfies the challenge. Nice nature shot.</td>', 'Good DOF. Satisfies the challenge. Nice nature shot.', '2004-06-07 23:54:30.000000', NULL, 1),
