(754308, 81150, 3306, '<td valign="top">I like it but would have liked it better rotated counterclockwise.</td>', 'I like it but would have liked it better rotated counterclockwise.', '2004-06-07 23:56:51.000000', NULL, 1),
(754310, 81312, 3306, '<td valign="top">Very nice. I like the colors.</td>', 'Very nice. I like the colors.', '2004-06-07 23:57:24.000000', NULL, 1),
