(758794, 81312, 18834, '<td valign="top">amazing shot, very clear view and moset definatly meets the challenge. 10.</td>', 'amazing shot, very clear view and moset definatly meets the challenge. 10.', '2004-06-10 16:10:01.000000', NULL, 1),
(758795, 81964, 18834, '<td valign="top">a little dark</td>', 'a little dark', '2004-06-10 16:10:23.000000', NULL, 1),
