(758937, 81964, 22877, '<td valign="top">Nicely done. Fit the challenge theme perfectly.</td>', 'Nicely done. Fit the challenge theme perfectly.', '2004-06-10 18:36:44.000000', NULL, 1),
(759019, 81963, 16965, '<td valign="top">I like the path, and the depth of field is perfect, but the overexposed area in the bottom-center is eye catching.  It might have made more impact if the image was taken from the other direction, with the bright area in the distance</td>', 'I like the path, and the depth of field is perfect, but the overexposed area in the bottom-center is eye catching.  It might have made more impact if the image was taken from the other direction, with the bright area in the distance', '2004-06-10 20:17:40.000000', NULL, 1),
