(759056, 81872, 2983, '<td valign="top">A nice scene, but I think it''s a little too sharp for a scene that is naturally noisy.</td>', 'A nice scene, but I think it''s a little too sharp for a scene that is naturally noisy.', '2004-06-10 20:54:26.000000', NULL, 1),
(759091, 80789, 19952, '<td valign="top">Nice bright colors and deep focal range. The focus throughout seems a bit soft, but consistently so.  Really nice photo overall - good job!</td>', 'Nice bright colors and deep focal range. The focus throughout seems a bit soft, but consistently so.  Really nice photo overall - good job!', '2004-06-10 21:37:22.000000', NULL, 1),
