(760287, 80655, 10608, '<td valign="top">stunning</td>', 'stunning', '2004-06-11 23:31:54.000000', NULL, 1),
(760496, 81528, 14603, '<td valign="top">Nice range of colours from blue through yellow to green..may not be clear enough focus in the distance to fully comply with the challenge (for some).. but I really like this image.<br/>Good work</td>', 'Nice range of colours from blue through yellow to green..may not be clear enough focus in the distance to fully comply with the challenge (for some).. but I really like this image.Good work', '2004-06-12 08:58:00.000000', NULL, 1),
(760498, 81954, 14603, '<td valign="top">Good idea, well captured...perhaps a little dark in some of the foliage areas,  but overall, very suitable for the challenge</td>', 'Good idea, well captured...perhaps a little dark in some of the foliage areas,  but overall, very suitable for the challenge', '2004-06-12 09:02:51.000000', NULL, 1),
(760502, 81790, 5792, '<td valign="top">Great concept. You will want to make the horizon level.</td>', 'Great concept. You will want to make the horizon level.', '2004-06-12 09:18:22.000000', NULL, 1),
(760509, 81964, 5792, '<td valign="top">Excellent perspective and framing. A very nice image with good DOF. Quality is above average. As an advanced challenge you might consider cloning out the building on the lower left of the Washington Monument and the cars just in front of it.</td>', 'Excellent perspective and framing. A very nice image with good DOF. Quality is above average. As an advanced challenge you might consider cloning out the building on the lower left of the Washington Monument and the cars just in front of it.', '2004-06-12 09:53:03.000000', NULL, 1),
(760510, 81132, 5792, '<td valign="top">Gorgeous, gorgeous landscape. Ribbon material all the way.</td>', 'Gorgeous, gorgeous landscape. Ribbon material all the way.', '2004-06-12 09:54:14.000000', NULL, 1),
(760514, 81069, 5792, '<td valign="top">You have done a masterful job. Simple yet extraordinary. Well thought out and very high technical quality. Outstanding work.</td>', 'You have done a masterful job. Simple yet extraordinary. Well thought out and very high technical quality. Outstanding work.', '2004-06-12 10:05:36.000000', NULL, 1),
(760516, 81455, 5792, '<td valign="top">There are not enough superlatives to describe how great this image is. Outside of being slightly dark on the left side of the image this is perfection. Outstanding, wonderful work. A very memorable image that transcends the challenge and moves into fine art photography. Kudos to you.</td>', 'There are not enough superlatives to describe how great this image is. Outside of being slightly dark on the left side of the image this is perfection. Outstanding, wonderful work. A very memorable image that transcends the challenge and moves into fine art photography. Kudos to you.', '2004-06-12 10:09:07.000000', NULL, 1),
(760517, 81806, 17377, '<td valign="top">I really like this photo. What I may have done is...had the subject more at the bottom left of the photo to maximize the negative space.</td>', 'I really like this photo. What I may have done is...had the subject more at the bottom left of the photo to maximize the negative space.', '2004-06-12 10:12:24.000000', NULL, 1),
(760519, 81909, 17377, '<td valign="top">Believe if or not.... this is the first entry that I believe really meets the challenge! I have not voted on all of them yet, but this is the best so far. 9</td>', 'Believe if or not.... this is the first entry that I believe really meets the challenge! I have not voted on all of them yet, but this is the best so far. 9', '2004-06-12 10:17:47.000000', NULL, 1),
(760543, 81557, 10402, '<td valign="top">The clouds make a great backdrop for the building, which is nicely proportioned. The subject is slightly underexposed, giving it a pleasing low-key appearance consistent with the overall mood of the image. Great job.</td>', 'The clouds make a great backdrop for the building, which is nicely proportioned. The subject is slightly underexposed, giving it a pleasing low-key appearance consistent with the overall mood of the image. Great job.', '2004-06-12 11:00:58.000000', NULL, 1),
(760552, 81962, 10402, '<td valign="top">Nice deep DOF with a pleasingly soft focus, but so cluttered it loses its impact.</td>', 'Nice deep DOF with a pleasingly soft focus, but so cluttered it loses its impact.', '2004-06-12 11:11:01.000000', NULL, 1),
(760569, 80457, 10402, '<td valign="top">Ahhh, you''ve discovered the secret to deep DOF: use a long telephoto and shoot something far away! I''d have been really impressed if you could have arranged to include a perfectly focused bird flying across...<br/> <br/>Although overexposed on the edges, this image nicely shows both the interesting craters at the terminator and the beautiful ray systems of several prominent craters, especially Copernicus.</td>', 'Ahhh, you''ve discovered the secret to deep DOF: use a long telephoto and shoot something far away! I''d have been really impressed if you could have arranged to include a perfectly focused bird flying across... Although overexposed on the edges, this image nicely shows both the interesting craters at the terminator and the beautiful ray systems of several prominent craters, especially Copernicus.', '2004-06-12 11:29:24.000000', NULL, 1),
(760572, 81704, 10402, '<td valign="top">The unusual viewpoint deep DOF gives this a nice abstract feeling. Nice colors. I''d have cropped off about half of the black area at the top, but that''s just me.</td>', 'The unusual viewpoint deep DOF gives this a nice abstract feeling. Nice colors. I''d have cropped off about half of the black area at the top, but that''s just me.', '2004-06-12 11:38:44.000000', NULL, 1),
(760576, 81524, 10402, '<td valign="top">Magnificent. I love the detail and the great textures here.</td>', 'Magnificent. I love the detail and the great textures here.', '2004-06-12 11:41:14.000000', NULL, 1),
(760580, 81650, 10402, '<td valign="top">Nice composition. I really like the pallette of colors that appear here; they go well together and give the image a nice nostaligic feeling.</td>', 'Nice composition. I really like the pallette of colors that appear here; they go well together and give the image a nice nostaligic feeling.', '2004-06-12 11:48:28.000000', NULL, 1),
(760587, 81906, 10402, '<td valign="top">Nice contrasts here, and effective use of deep DOF.</td>', 'Nice contrasts here, and effective use of deep DOF.', '2004-06-12 11:52:51.000000', NULL, 1),
(760593, 81788, 14438, '<td valign="top">Nice title ;o)</td>', 'Nice title ;o)', '2004-06-12 11:57:43.000000', NULL, 1),
(760596, 81606, 10402, '<td valign="top">The few assymetrical elements add interest to a lackluster image. But there is still not a good center of focus to serve as an anchor for the viewer as he explores the photo.</td>', 'The few assymetrical elements add interest to a lackluster image. But there is still not a good center of focus to serve as an anchor for the viewer as he explores the photo.', '2004-06-12 12:03:00.000000', NULL, 1),
(760604, 81296, 10402, '<td valign="top">Nicely balanced composition, but appears oversharpened, putting halos around the lilac.</td>', 'Nicely balanced composition, but appears oversharpened, putting halos around the lilac.', '2004-06-12 12:09:17.000000', NULL, 1),
(760609, 81953, 10402, '<td valign="top">Good composition and wonderful lighting. Slightly slanted, but overall a pleasing image.</td>', 'Good composition and wonderful lighting. Slightly slanted, but overall a pleasing image.', '2004-06-12 12:14:11.000000', NULL, 1),
(760611, 81132, 10402, '<td valign="top">I love the clarity of the water and the way it reflects the landscape and clouds. The rustic pier adds a nice touch.</td>', 'I love the clarity of the water and the way it reflects the landscape and clouds. The rustic pier adds a nice touch.', '2004-06-12 12:17:13.000000', NULL, 1),
(760616, 80655, 10402, '<td valign="top">Great point of view with a good background. The border is appropriate to the subject and works well here.</td>', 'Great point of view with a good background. The border is appropriate to the subject and works well here.', '2004-06-12 12:21:01.000000', NULL, 1),
(760618, 81822, 10402, '<td valign="top">The field and tree are nice, but the clouds really set the mood for this image.</td>', 'The field and tree are nice, but the clouds really set the mood for this image.', '2004-06-12 12:23:26.000000', NULL, 1),
(760626, 81584, 10402, '<td valign="top">Nice dynamic composition.</td>', 'Nice dynamic composition.', '2004-06-12 12:36:22.000000', NULL, 1),
(760628, 81826, 10402, '<td valign="top">The black bird makes a nice contrast, but is too close to the bottom of the frame. A lower point of view might have avoided this.</td>', 'The black bird makes a nice contrast, but is too close to the bottom of the frame. A lower point of view might have avoided this.', '2004-06-12 12:38:30.000000', NULL, 1),
(760630, 81942, 10402, '<td valign="top">Great juxtaposition and very effective use of deep DOF. The horizontal stem is a subtle and symbolic touch.</td>', 'Great juxtaposition and very effective use of deep DOF. The horizontal stem is a subtle and symbolic touch.', '2004-06-12 12:40:37.000000', NULL, 1),
(760635, 81941, 10402, '<td valign="top">The choppy water and fog enshrouded city make this image very moody, a feeling enhanced by using black and white. The deep DOF is a bit hard to make out through the fog.</td>', 'The choppy water and fog enshrouded city make this image very moody, a feeling enhanced by using black and white. The deep DOF is a bit hard to make out through the fog.', '2004-06-12 12:44:05.000000', NULL, 1),
(760648, 81289, 10402, '<td valign="top">The flowers nicely frame the landscape; the contrast between foreground and background works well. A few technical nits: the mountains seem a bit oversharpened and there are some distracting compression artifacts.</td>', 'The flowers nicely frame the landscape; the contrast between foreground and background works well. A few technical nits: the mountains seem a bit oversharpened and there are some distracting compression artifacts.', '2004-06-12 13:05:25.000000', NULL, 1),
(760650, 81697, 10402, '<td valign="top">I suppose the water towers in the background have a symbolic connection to the water in the fountain, but their character doesn''t really fit the rest of the image.</td>', 'I suppose the water towers in the background have a symbolic connection to the water in the fountain, but their character doesn''t really fit the rest of the image.', '2004-06-12 13:08:17.000000', NULL, 1),
(760652, 81312, 10402, '<td valign="top">The composition here has a great balance. All the elements fit together very well.</td>', 'The composition here has a great balance. All the elements fit together very well.', '2004-06-12 13:10:39.000000', NULL, 1),
(760661, 81290, 10402, '<td valign="top">Breathtakingly beautiful. Skilled adjustment with curves could enhance some of the details in the mountains, but the image is fine without that.</td>', 'Breathtakingly beautiful. Skilled adjustment with curves could enhance some of the details in the mountains, but the image is fine without that.', '2004-06-12 13:32:23.000000', NULL, 1),
(760676, 81477, 10402, '<td valign="top">My daughter thinks the dogs are cute! I do too, but wonder if they add to the photo. Either way, I think a lower camera angle would work better, and if you have one, a polarizer filter to reduce some of the glare from the water. Great title.</td>', 'My daughter thinks the dogs are cute! I do too, but wonder if they add to the photo. Either way, I think a lower camera angle would work better, and if you have one, a polarizer filter to reduce some of the glare from the water. Great title.', '2004-06-12 13:48:34.000000', NULL, 1),
(760680, 81710, 10402, '<td valign="top">Motion blur is an essential element here, but there is so much that the car is completely unrecognizable. Using a shutter speed fast enough to capture the car with just a little blur would have made it difficult to get the deep DOF for the challenge, but would have resulted in a better image.</td>', 'Motion blur is an essential element here, but there is so much that the car is completely unrecognizable. Using a shutter speed fast enough to capture the car with just a little blur would have made it difficult to get the deep DOF for the challenge, but would have resulted in a better image.', '2004-06-12 13:57:21.000000', NULL, 1),
(760684, 81768, 10402, '<td valign="top">The coil of wire completes the story, but is unobtrusively placed so it doesn''t detract from the beauty of the scene. Nicely done.</td>', 'The coil of wire completes the story, but is unobtrusively placed so it doesn''t detract from the beauty of the scene. Nicely done.', '2004-06-12 14:02:31.000000', NULL, 1),
(760687, 81909, 10402, '<td valign="top">Great idea, and although the background isn''t completely in focus the DOF is deep enough to give a nice impressionistic effect. The thumbnail is too distracting.</td>', 'Great idea, and although the background isn''t completely in focus the DOF is deep enough to give a nice impressionistic effect. The thumbnail is too distracting.', '2004-06-12 14:07:52.000000', NULL, 1),
(760693, 81426, 10402, '<td valign="top">Nice use of selective color.</td>', 'Nice use of selective color.', '2004-06-12 14:14:01.000000', NULL, 1),
(760695, 81243, 10402, '<td valign="top">Nice juxtaposition of the natural and artificial, although I can''t help wondering how it would be in a landscape format.</td>', 'Nice juxtaposition of the natural and artificial, although I can''t help wondering how it would be in a landscape format.', '2004-06-12 14:18:19.000000', NULL, 1),
(760699, 81717, 10402, '<td valign="top">This would be a great photo if the inside of the tower was in focus and the sky was a bit more interesting.</td>', 'This would be a great photo if the inside of the tower was in focus and the sky was a bit more interesting.', '2004-06-12 14:32:02.000000', NULL, 1),
(760705, 81622, 10402, '<td valign="top">Needs a bit more contrast and a lot less clutter.</td>', 'Needs a bit more contrast and a lot less clutter.', '2004-06-12 14:36:58.000000', NULL, 1),
(760709, 81723, 10402, '<td valign="top">Morning light is usually magical and works here very well. Great composition.</td>', 'Morning light is usually magical and works here very well. Great composition.', '2004-06-12 14:39:59.000000', NULL, 1),
(760725, 81956, 10402, '<td valign="top">Nice pastoral scene with great DOF. Could benefit from some postprocessing to tweak the contrast and remove the color cast.</td>', 'Nice pastoral scene with great DOF. Could benefit from some postprocessing to tweak the contrast and remove the color cast.', '2004-06-12 14:51:24.000000', NULL, 1),
(760731, 81832, 10402, '<td valign="top">Interesting subjects with good composition and lighting. But the back subjects are not in focus and that is distracting. This would be a great photo if it had deep DOF.</td>', 'Interesting subjects with good composition and lighting. But the back subjects are not in focus and that is distracting. This would be a great photo if it had deep DOF.', '2004-06-12 14:56:28.000000', NULL, 1),
(760762, 81795, 13897, '<td valign="top">Elmhurst? Nice shot, I like the way the buildings look, one with windows and one without and on either side of the engine.</td>', 'Elmhurst? Nice shot, I like the way the buildings look, one with windows and one without and on either side of the engine.', '2004-06-12 16:13:45.000000', NULL, 1),
(760778, 81531, 20662, '<td valign="top">Okay -- being afraid of heights, this one gives me the creeps.  You''ve suceeded with the deep depth of field or it wouldn''t bother me to be looking down!</td>', 'Okay -- being afraid of heights, this one gives me the creeps.  You''ve suceeded with the deep depth of field or it wouldn''t bother me to be looking down!', '2004-06-12 16:31:31.000000', NULL, 1),
(760781, 80655, 5391, '<td valign="top">My goodness.  Not used to seeing something like this so in focus the whole way through.  Excellent job on the challenge.</td>', 'My goodness.  Not used to seeing something like this so in focus the whole way through.  Excellent job on the challenge.', '2004-06-12 16:35:02.000000', NULL, 1),
(760783, 81906, 20662, '<td valign="top">One of my favorite places! Best views of the city from there.</td>', 'One of my favorite places! Best views of the city from there.', '2004-06-12 16:37:30.000000', NULL, 1),
(760786, 81806, 15595, '<td valign="top">i reeeeeeeeeeeely like this pic.. everything.. sky is fascinanting</td>', 'i reeeeeeeeeeeely like this pic.. everything.. sky is fascinanting', '2004-06-12 16:39:55.000000', NULL, 1),
(760788, 81069, 1202, '<td valign="top">My top pick, good job.   10</td>', 'My top pick, good job.   10', '2004-06-12 16:54:54.000000', NULL, 1),
(760790, 81132, 10818, '<td valign="top">That is just beautiful, the reflection is awesome, and the clear water looks perfect for skinny dipping.  :)  Fantastic photo !  10</td>', 'That is just beautiful, the reflection is awesome, and the clear water looks perfect for skinny dipping.  :)  Fantastic photo !  10', '2004-06-12 16:58:58.000000', NULL, 1),
(760791, 81271, 10818, '<td valign="top">What an awesome farm, I love the hills in the background.  Beautiful photo.</td>', 'What an awesome farm, I love the hills in the background.  Beautiful photo.', '2004-06-12 17:00:40.000000', NULL, 1),
(760793, 81135, 5112, '<td valign="top">Long exposure?  Good work!</td>', 'Long exposure?  Good work!', '2004-06-12 17:05:40.000000', NULL, 1),
(760797, 81809, 5112, '<td valign="top">Hey, I like this picture!  Fits the challenge quite nicely.  The blues and greens are very beautiful, but the silhouette really makes the picture, especially the guy on the right.  The grass showing through at the bottom of the silhouette adds a nice touch.  This would have fit the other challenge (Waiting) also.  Good work!</td>', 'Hey, I like this picture!  Fits the challenge quite nicely.  The blues and greens are very beautiful, but the silhouette really makes the picture, especially the guy on the right.  The grass showing through at the bottom of the silhouette adds a nice touch.  This would have fit the other challenge (Waiting) also.  Good work!', '2004-06-12 17:06:35.000000', NULL, 1),
(760842, 81956, 4767, '<td valign="top">Shouldn''t the title be more like... "Another Snowbird Stays in Cali" ????  (I THINK they come from Canada).</td>', 'Shouldn''t the title be more like... "Another Snowbird Stays in Cali" ????  (I THINK they come from Canada).', '2004-06-12 18:26:07.000000', NULL, 1),
(760889, 81341, 7560, '<td valign="top">You and I must have passed cameras. :) I was at Arlington earlier in the morning when it was still raining. Excellent shot! I like the darker sides with a feeling of a lit center area. <br/>9</td>', 'You and I must have passed cameras. :) I was at Arlington earlier in the morning when it was still raining. Excellent shot! I like the darker sides with a feeling of a lit center area. 9', '2004-06-12 19:20:52.000000', NULL, 1),
(760890, 81069, 7560, '<td valign="top">I love the use of frame within a frame in this shot. Great sky color. Photoshop or was it a polarizer? 9</td>', 'I love the use of frame within a frame in this shot. Great sky color. Photoshop or was it a polarizer? 9', '2004-06-12 19:22:07.000000', NULL, 1),
(760891, 81008, 7560, '<td valign="top">I ususally don''t like plane shots. This is a great exception to that. The addition of the well exposed plan engine adds a different perspective. It helps the image tell a stronger story. Nice composition and color. 8</td>', 'I ususally don''t like plane shots. This is a great exception to that. The addition of the well exposed plan engine adds a different perspective. It helps the image tell a stronger story. Nice composition and color. 8', '2004-06-12 19:23:25.000000', NULL, 1),
(760893, 81132, 7560, '<td valign="top">This shot was an automatic 10. It''s the first and only shot in the challenge this week that made me just say wow! I love the clarity and stillness of the water, The shadows on the water, and the slight tilt to the end of the pier. There are just so many amazing elements to this image. Beautiful symmetry, texture, solid composition. Just spectacular. 10</td>', 'This shot was an automatic 10. It''s the first and only shot in the challenge this week that made me just say wow! I love the clarity and stillness of the water, The shadows on the water, and the slight tilt to the end of the pier. There are just so many amazing elements to this image. Beautiful symmetry, texture, solid composition. Just spectacular. 10', '2004-06-12 19:25:29.000000', NULL, 1),
(760895, 81727, 7560, '<td valign="top">The cicada has landed! Great way to add interest to a normalliy static subject. The subject is almost too close to center. If possible, I''d recrop the moon, and shift either left or right. Awesome idea! 7</td>', 'The cicada has landed! Great way to add interest to a normalliy static subject. The subject is almost too close to center. If possible, I''d recrop the moon, and shift either left or right. Awesome idea! 7', '2004-06-12 19:27:28.000000', NULL, 1),
(760901, 81591, 8023, '<td valign="top">Love it!</td>', 'Love it!', '2004-06-12 19:39:31.000000', NULL, 1),
(760903, 80826, 2158, '<td valign="top">Cute picture, but this one belongs in shallow depth of field.</td>', 'Cute picture, but this one belongs in shallow depth of field.', '2004-06-12 19:51:12.000000', NULL, 1),
(760979, 81135, 3306, '<td valign="top">Well done. Great image. One of my favorites. Should be a ribbon winner.</td>', 'Well done. Great image. One of my favorites. Should be a ribbon winner.', '2004-06-12 22:48:33.000000', NULL, 1),
(760981, 81298, 6520, '<td valign="top">10</td>', '10', '2004-06-12 22:51:25.000000', NULL, 1),
(760985, 81524, 6520, '<td valign="top">9</td>', '9', '2004-06-12 22:56:13.000000', NULL, 1),
