(760989, 81957, 6520, '<td valign="top">9</td>', '9', '2004-06-12 22:58:45.000000', NULL, 1),
(760991, 81053, 6520, '<td valign="top">8</td>', '8', '2004-06-12 22:59:21.000000', NULL, 1),
