(761244, 81682, 8624, '<td valign="top">fun shot. I think oit would have been even stronger cropped in tighter eliminating the non balloon elements of the left of the fram and drawing more attention to the person pulling the center cord.</td>', 'fun shot. I think oit would have been even stronger cropped in tighter eliminating the non balloon elements of the left of the fram and drawing more attention to the person pulling the center cord.', '2004-06-13 10:26:03.000000', NULL, 1),
(761246, 81832, 8624, '<td valign="top">I think this is more an example of shallow depth of field</td>', 'I think this is more an example of shallow depth of field', '2004-06-13 10:28:29.000000', NULL, 1),
(761248, 81902, 8125, '<td valign="top">What a beautiful shot.  I love the green grass, everything about the two horses and the sky.... Just a gorgeous photo...</td>', 'What a beautiful shot.  I love the green grass, everything about the two horses and the sky.... Just a gorgeous photo...', '2004-06-13 10:29:45.000000', NULL, 1),
