(761272, 80826, 8125, '<td valign="top">Sorry, this is not deep dof.  If it were, everything in the background would be in focus.</td>', 'Sorry, this is not deep dof.  If it were, everything in the background would be in focus.', '2004-06-13 10:48:42.000000', NULL, 1),
