(761965, 81150, 811, '<td valign="top">Awesome use of an unusual angle to give the picture interest!</td>', 'Awesome use of an unusual angle to give the picture interest!', '2004-06-14 00:18:50.000000', NULL, 1),
(761973, 81677, 17203, '<td valign="top">That''s about as shallow a DOF as you can get.</td>', 'That''s about as shallow a DOF as you can get.', '2004-06-14 00:26:43.000000', NULL, 1),
