(761976, 81776, 17203, '<td valign="top">Wow. Foreground is a tad dark, but I like the color and you''ve CERTAINLY shown deep DOF.</td>', 'Wow. Foreground is a tad dark, but I like the color and you''ve CERTAINLY shown deep DOF.', '2004-06-14 00:29:07.000000', NULL, 1),
(761978, 81053, 17203, '<td valign="top">I only see far, not near and far. Essentially all focus is on infinity. A lower crop might solve this.</td>', 'I only see far, not near and far. Essentially all focus is on infinity. A lower crop might solve this.', '2004-06-14 00:31:34.000000', NULL, 1),
(761981, 81953, 17203, '<td valign="top">Geez, can I wait for the monorail? This looks 2 miles long.</td>', 'Geez, can I wait for the monorail? This looks 2 miles long.', '2004-06-14 00:33:08.000000', NULL, 1),
(761984, 81938, 17203, '<td valign="top">I don''t understand the foreground. Are we looking through something way out of focus?</td>', 'I don''t understand the foreground. Are we looking through something way out of focus?', '2004-06-14 00:34:40.000000', NULL, 1),
(761989, 81902, 17203, '<td valign="top">Looks like a good postcard photo. Color is a little dull though, and I see some odd burning and dodging spots.</td>', 'Looks like a good postcard photo. Color is a little dull though, and I see some odd burning and dodging spots.', '2004-06-14 00:36:11.000000', NULL, 1),
(761990, 81455, 17203, '<td valign="top">Can''t wait to find out what Ansel Adams uses for a screen name. Welcome to DPC! 8</td>', 'Can''t wait to find out what Ansel Adams uses for a screen name. Welcome to DPC! 8', '2004-06-14 00:37:18.000000', NULL, 1),
(761993, 81651, 17203, '<td valign="top">I spend a lot of time thinking of interesting subjects, and here you might very well nab a ribbon with a shot of weeds. -sigh- 9</td>', 'I spend a lot of time thinking of interesting subjects, and here you might very well nab a ribbon with a shot of weeds. -sigh- 9', '2004-06-14 00:39:10.000000', NULL, 1),
